-- Mood: same profile as harvester/cuscope/loadgen.py (UTC-6 local time).
DECLARE @local datetime2(0) = DATEADD(hour, -6, SYSUTCDATETIME());
DECLARE @h int = DATEPART(hour, @local);
DECLARE @doy int = DATEPART(dayofyear, @local);
DECLARE @bucket int = (@doy * @doy * 31 + @doy * 17) % 101 % 10;
DECLARE @day float = CASE WHEN DATEDIFF(day, '19000101', @local) % 7 >= 5 THEN 0.3
                          WHEN @bucket < 2 THEN 0.4 WHEN @bucket < 6 THEN 1.0 WHEN @bucket < 9 THEN 1.8 ELSE 2.6 END;
DECLARE @hour float = CASE WHEN @h BETWEEN 8 AND 17 THEN 1.5 WHEN @h BETWEEN 18 AND 21 THEN 0.8 ELSE 0.4 END;
DECLARE @block int = @doy * 12 + @h / 2;
DECLARE @storm float = CASE WHEN (@block * @block * 31 + @block * 17 + 5) % 101 % 10 = 9 THEN 4.0 ELSE 1.0 END;
-- Exponential run size (mean 1): mostly small, sometimes huge.
DECLARE @noise float = -LOG((ABS(CHECKSUM(NEWID())) % 999 + 1) / 1000.0);
DECLARE @mood float = CASE WHEN @day * @hour * @storm > 8 THEN 8 ELSE @day * @hour * @storm END * @noise;
-- Stochastic rounding keeps the expected number of passes equal to the mood.
DECLARE @passes int = FLOOR(@mood + (ABS(CHECKSUM(NEWID())) % 100) / 100.0);
IF @passes > 10 SET @passes = 10;
DECLARE @i int = 0;
WHILE @i < @passes
BEGIN
    IF @i = 0
    BEGIN
        DROP TABLE IF EXISTS dbo.agg_hourly;
        CREATE TABLE dbo.agg_hourly AS
        SELECT CAST(DATEADD(hour, DATEDIFF(hour, 0, event_time), 0) AS datetime2(0)) AS hour_bucket, category, region,
               COUNT_BIG(*) AS events, SUM(amount) AS amount, SUM(qty) AS qty
        FROM lh_loadgen.dbo.synthetic_events
        GROUP BY DATEADD(hour, DATEDIFF(hour, 0, event_time), 0), category, region
        OPTION (LABEL = 'loadgen_ctas');
    END
    ELSE
    BEGIN
        -- Extra passes are the ad-hoc analyst work of a busy day: a wider, minute-level rollup.
        DROP TABLE IF EXISTS dbo.agg_minute;
        CREATE TABLE dbo.agg_minute AS
        SELECT CAST(DATEADD(minute, DATEDIFF(minute, 0, event_time), 0) AS datetime2(0)) AS minute_bucket, category,
               region, COUNT_BIG(*) AS events, COUNT(DISTINCT qty) AS qty_values, SUM(amount) AS amount
        FROM lh_loadgen.dbo.synthetic_events
        GROUP BY DATEADD(minute, DATEDIFF(minute, 0, event_time), 0), category, region
        OPTION (LABEL = 'loadgen_ctas_detail');
    END
    SET @i = @i + 1;
END
